<template><view class="page">
  <view class="head"><text class="eyebrow">RESERVATIONS</text><text class="title">我的订单</text><text class="count">{{activeCount}} 个有效预订</text></view>
  <view class="tabs"><text class="active">全部</text><text>待到店</text><text>已完成</text><text>已取消</text></view>
  <view v-if="!orders.length" class="empty"><view class="empty-icon">⌁</view><text class="empty-title">今晚还没有安排</text><text class="muted">挑一个喜欢的台位，开始你的夜晚</text><button @click="goBooking">查看台位</button></view>
  <view v-else class="list"><view v-for="order in orders" :key="order.id" :class="['order',order.status]">
    <view class="order-head"><view><text class="order-label">HOLE CLUB</text><text class="id">{{order.id}}</text></view><text class="status">{{order.status==='reserved'?'待到店':'已取消'}}</text></view>
    <view class="date-block"><view class="day"><b>{{day(order.date)}}</b><span>{{month(order.date)}}</span></view><view><text class="date">{{order.date}}</text><text class="time">{{order.session}} 入场</text></view></view>
    <view class="line"></view><view class="info"><view><span>预订台位</span><b>{{order.seats.join('、')}}</b></view><view><span>预订人</span><b>{{order.guestName}} · {{mask(order.phone)}}</b></view></view>
    <button v-if="order.status==='reserved'" class="cancel" @click="cancel(order.id)">取消预订</button>
  </view></view>
  <view class="nav"><view @click="goHome"><text>○</text><span>首页</span></view><view @click="goBooking"><text>⌁</text><span>订台</span></view><view class="active"><text>≡</text><span>订单</span></view><view @click="goMember"><text>◇</text><span>我的</span></view></view>
</view></template>
<script setup lang="ts">
import {computed,ref} from 'vue';import{onShow}from'@dcloudio/uni-app';import{getOrders,cancelOrder,type ClubOrder}from'../../services/orders'
const orders=ref<ClubOrder[]>([]);onShow(()=>orders.value=getOrders());const activeCount=computed(()=>orders.value.filter(o=>o.status==='reserved').length)
const go=(url:string)=>uni.redirectTo({url}),goHome=()=>go('/pages/index/index'),goBooking=()=>go('/pages/booking/index'),goMember=()=>go('/pages/member/index')
const mask=(p:string)=>p.replace(/(\d{3})\d{4}(\d+)/,'$1****$2'),day=(d:string)=>d.slice(-2),month=(d:string)=>['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'][Number(d.slice(5,7))-1]
const cancel=(id:string)=>uni.showModal({title:'取消预订',content:'确认取消这笔预订吗？',success:r=>{if(r.confirm){cancelOrder(id);orders.value=getOrders()}}})
</script>
<style scoped>
