}.info span{font-size:10px;color:#676770}.info b{font-size:11px}.cancel{height:38px;margin:15px 0 0;background:transparent;border:1px solid #383840;color:#999;border-radius:5px;font-size:10px}.nav{position:fixed;z-index:10;bottom:0;left:50%;transform:translateX(-50%);width:min(480px,100%);height:70px;background:rgba(13,13,18,.96);border-top:1px solid #22222a;display:grid;grid-template-columns:repeat(4,1fr)}.nav view{display:flex;flex-direction:column;align-items:center;justify-content:center;color:#62626b;font-size:17px}.nav span{font-size:9px;margin-top:4px}.nav .active{color:#d7ff3f}
</style>
